        lastAngle = angle
        guard angle >= 90 else { return }
        let restedFor = lastMove > 0 ? now - lastMove : 0
        if angle > openAngle || (restedFor > 1.5 && abs(angle - openAngle) > 0.5) {
            openAngle = angle
            UserDefaults.standard.set(angle, forKey: "openAngle")
            renderer?.setOpenAngle(angle)
        }
